SELECT id,paper_id,pmid,doi,paper_title title,publish_year pub_year,journal_name journal_title,bioproject_accession,abstract_text,affiliation_info,keyword_list,authors_json,mesh_headings_json,grants_json,cncb_banks_json FROM genbase_publication
WHERE openlb_status='PENDING' AND paper_id IS NOT NULL AND is_primary=1
ORDER BY id LIMIT #{limit}
